"""01/11/2026: nove lições adicionais; citações identificadas e exemplos criados."""
from licoes_20261101 import lesson, read, choice, vf, pairs, order, fill, underline

CANTIGA='https://universocantigas.gal/cantigas/se-eu-podesse-desamar'
FARSA='https://pt.wikisource.org/wiki/Farsa_de_In%C3%AAs_Pereira'
VARIEDADES='https://ciberduvidas.iscte-iul.pt/artigos/rubricas/idioma/variantes-ou-variedades-de-portugues/5089'
CAMOES='https://ensina.rtp.pt/artigo/mudam-se-os-tempos-mudam-se-as-vontades-de-luis-de-camoes/'
MAIAS='https://www.gutenberg.org/cache/epub/40409/pg40409-images.html'
CARTA='https://imprensanacional.pt/wp-content/uploads/2022/03/Amor-Perdicao.pdf'
ANTERO='https://www.arqnet.pt/portal/discursos/maio01.html'
CESARIO='https://www.gutenberg.org/cache/epub/8698/pg8698-images.html'

lesson('m5-f16','Aprender a viver',2,'m5-f10',
 'Que pode a educação explicar numa vida, e que fica por explicar?',[
 read('Aprender a viver','<p class="abre">Saber repetir uma resposta é o mesmo que saber compreender o mundo? E uma educação promissora garante uma vida conseguida?</p><p>Vais comparar práticas educativas em <i>Os Maias</i>, sem transformar a infância numa sentença sobre o futuro.</p>','Abre'),
 read('O essencial','<p>A <strong>caracterização indireta</strong> apresenta personagens através de ações, relações e hábitos. A comparação de educações envolve também os valores de quem narra e de quem comenta.</p><p>Uma influência não é uma causa única. Para explicar um percurso, é necessário relacionar formação, circunstâncias e escolhas posteriores.</p>','O essencial'),
 read('Pedro e Carlos','<p>No capítulo I, o padre Vasques ensina a Pedro as declinações latinas e a cartilha. A narração associa as perguntas e respostas a um estado dormente. No capítulo III, Brown adia o latim e põe primeiro a força física; Afonso apoia-o e defende que a criança conheça o mundo concreto.</p><blockquote class="prosa">«O latim era um luxo d’erudito»</blockquote><blockquote class="prosa">«deixando-o ao mesmo tempo sem saber o que é a chuva que o molha, como se faz o pão que come»</blockquote><p>Eça de Queirós, <i>Os Maias</i>, vol. I, Porto, Livraria Internacional de Ernesto Chardron, 1888. O resumo do padre Vasques vem do capítulo I (pp. 18–19); os dois recortes, do capítulo III (pp. 82–83). <a href="'+MAIAS+'" target="_blank" rel="noopener">Lê os episódios no texto integral do Projeto Gutenberg</a>, preparado a partir de exemplares de bibliotecas identificadas na edição digital.</p>'),
 choice('Que contraste organiza os exemplos educativos?', ['Repetição doutrinária e compreensão do mundo concreto.', 'Aprendizagem autónoma e ausência total de orientação.', 'Prática desportiva e rejeição de todos os conhecimentos.'],0,'A comparação opõe prioridades e métodos. O contraste não significa que Carlos cresça sem orientação ou que toda a aprendizagem verbal seja inútil.'),
 vf('A defesa do conhecimento concreto prova que o romance considera inútil toda a leitura.',False,'O recorte critica uma prioridade educativa que deixa por conhecer o mundo vivido. Não equivale a rejeitar qualquer leitura ou estudo.'),
 pairs('Relaciona cada elemento com a prática apresentada.',[['Pedro e o padre Vasques','Repetição da cartilha'],['Carlos e a orientação de Brown','Força física antes do latim'],['Afonso na discussão educativa','Apoio ao método defendido por Brown']], 'A atribuição permite distinguir quem aprende, quem orienta e quem avalia. A comparação não deve misturar todas as vozes numa opinião indiferenciada.'),
 read('Eusebiozinho e o futuro previsto','<blockquote class="prosa">«Assim na familia tinha a sua carreira destinada: era rico, havia de ser primeiro bacharel, e depois desembargador.»</blockquote><p>Eça de Queirós, mesma edição, capítulo III, p. 90. Conserva-se a grafia da transcrição. A passagem apresenta as expectativas da família de Eusebiozinho, depois de descrever o seu contacto precoce com livros e a admiração dos adultos.</p><p>O retrato cruza saber exibido, imobilidade e uma carreira projetada pelos outros. A ironia pede atenção à distância entre o elogio familiar e os pormenores narrativos.</p>'),
 fill('Completa a distinção.', 'A família apresenta uma [1] de carreira; a narração permite uma leitura [2].',[(['previsão','sentença','conclusão'],0),(['crítica','objetiva','factual'],0)],'A carreira está projetada, não realizada naquele momento. A narração oferece pormenores que permitem questionar o valor do modelo admirado pela família.'),
 order('Ordena uma comparação dos três percursos.', ['Identificar as práticas de cada educação','Distinguir os valores dos adultos envolvidos','Observar a apresentação narrativa','Relacionar a formação com escolhas posteriores'],'A comparação começa por provas concretas e não por rótulos. As escolhas posteriores podem complicar as expectativas produzidas pela educação.'),
 underline('Seleciona a palavra que mostra a carreira como decidida pelos outros.', 'Na família tinha a sua carreira destinada.', [6], '«Destinada» apresenta um futuro previamente traçado. A formulação convida a perguntar que margem de decisão é reconhecida à criança.'),
 choice('Que comentário evita uma explicação determinista?', ['A formação influencia escolhas sem as explicar sozinha.', 'A formação determina sozinha todos os atos de uma vida inteira.', 'A formação torna irrelevantes as decisões posteriores.'],0,'Influência e determinação total são conceitos diferentes. A análise do romance precisa de confrontar o modelo educativo com a vida posterior.'),
 vf('O entusiasmo dos adultos por Eusebiozinho impede uma leitura irónica do seu retrato.',False,'O contraste entre o elogio e os pormenores da apresentação pode sustentar a ironia. É precisamente necessário ler além da avaliação dos familiares.'),
 read('O método não resolve tudo','<p>No mesmo capítulo III, Carlos agride Eusebiozinho durante a convivência em Santa Olávia. Esse comportamento impede transformar o modelo educativo que recebe numa garantia de superioridade moral.</p><p>Comparar educações não exige humilhar uma criança. O objeto da análise são as práticas, as expectativas, as relações e o modo como a narrativa as apresenta.</p>'),
 pairs('Distingue três tipos de afirmação.',[['A criança repete respostas','Observação de uma prática'],['A família admira essa prática','Avaliação das personagens'],['Essa prática explica toda a vida','Generalização a demonstrar']], 'Uma observação e uma avaliação atribuída não bastam para estabelecer uma causa total. A generalização exigiria um alcance que os recortes não sustentam.'),
 choice('Que pergunta testa os limites de uma educação valorizada?', ['Como age Carlos quando convive com Eusebiozinho?', 'Que prova garante que Carlos nunca comete erros?', 'Como demonstra o método que a infância prevê tudo?'],0,'O comportamento concreto permite confrontar a promessa educativa com a ação. As outras perguntas já pressupõem a conclusão que deveria ser discutida.'),
 fill('Completa uma conclusão.', 'Comparar exige observar [1]; explicar uma vida exige considerar [2].',[(['práticas','destinos','etiquetas'],0),(['escolhas','só notas','só planos'],0)],'As práticas oferecem provas para a comparação. As escolhas e circunstâncias posteriores impedem reduzir toda a existência a um esquema da infância.'),
 order('Planeia uma resposta comparativa.', ['Escolher uma prática de cada modelo','Explicar o valor que os adultos lhe atribuem','Confrontar o elogio com um pormenor narrativo','Apresentar uma conclusão com um limite'],'A conclusão deve conservar as diferenças e o papel da narração. Uma tabela de características não substitui a interpretação dos seus efeitos.'),
 choice('Que proposta transfere a questão para um caso criado?', ['Comparar repetir uma regra com aplicá-la a um caso novo.', 'Prever uma vida inteira apenas pela primeira resposta.', 'Classificar todas as pessoas pelo prestígio da sua família.'],0,'Aplicar a um caso novo permite testar a compreensão. As outras propostas reproduzem o determinismo ou a hierarquia social que a leitura deve interrogar.'),
 vf('Uma educação valorizada na narrativa pode coexistir com comportamentos censuráveis de quem a recebeu.',True,'O episódio entre Carlos e Eusebiozinho mostra a necessidade de distinguir método e conduta. A comparação não cria pessoas infalíveis.'),
 read('Para levar','<p class="levar">A educação ajuda a explicar uma vida; não a decide por inteiro.</p><p>Compara uma prática, uma expectativa e um comportamento. Explica o que a comparação permite concluir e o que continua por explicar.</p>','Para levar'),
])

lesson('m6-f14','Discordar sem excluir',1,'m6-f13',
 'Como se pode defender uma ideia e aceitar que ela seja contrariada?',[
 read('Discordar sem excluir','<p class="abre">Se alguém discorda de ti, deixou de poder pensar contigo? A abertura de uma conferência pode definir a relação com o público antes de apresentar a tese.</p><p>Vais distinguir respeito pelas pessoas, exame das ideias e condições de uma discussão.</p>','Abre'),
 read('O essencial','<p>O <strong>ethos</strong> é a imagem de quem fala construída no discurso. Uma <strong>concessão</strong> reconhece um ponto que poderia favorecer uma objeção, sem abandonar necessariamente a tese.</p><p>A <strong>refutação</strong> enfrenta uma ideia com razões. Atacar a identidade de quem a apresenta não substitui esse trabalho.</p>','O essencial'),
 read('Um público que pode discordar','<blockquote class="prosa">«Não posso pois apelar para a fraternidade das ideias: conheço que as minhas palavras não devem ser bem aceites por todos.»</blockquote><blockquote class="prosa">«não pretendemos impor as nossas opiniões, mas simplesmente expô-las: não pedimos a adesão das pessoas que nos escutam; pedimos só a discussão»</blockquote><p>Antero de Quental, <i>Causas da Decadência dos Povos Peninsulares nos Últimos Três Séculos</i>, conferência de 27 de maio de 1871, abertura, transcrição no <a href="'+ANTERO+'" target="_blank" rel="noopener">Portal da História, com o texto integral</a>. A página não identifica a edição impressa usada.</p><p>O segundo recorte retoma uma declaração sobre as Conferências. O orador admite a divergência e propõe uma relação que não depende da concordância prévia.</p>'),
 choice('Que relação com o público é proposta?', ['A discussão das ideias admite a discordância.', 'A escuta das ideias exige a adesão antecipada.', 'A divergência das ideias impede todo o respeito.'],0,'O orador distingue ouvir e discutir de aderir. A relação com o público pode manter-se mesmo quando as opiniões não coincidem.'),
 vf('Recusar impor uma opinião significa não defender nenhuma tese.',False,'Uma tese pode ser defendida com razões e permanecer aberta à discussão. A alternativa à imposição não é necessariamente a ausência de posição.'),
 pairs('Relaciona cada expressão com a operação discursiva.',[['não devem ser bem aceites por todos','Reconhecer a divergência possível'],['não pretendemos impor','Recusar a adesão forçada'],['pedimos só a discussão','Propor o exame das ideias']], 'As expressões constroem uma relação com o auditório. A abertura prepara as condições da discussão antes de desenvolver as razões históricas.'),
 read('Uma fraternidade que não exige acordo','<p>Na abertura, Antero distingue a concordância de ideias de uma relação moral fundada na tolerância e no respeito. A disposição para discutir constrói uma imagem de sinceridade e de procura da verdade.</p><p>Essa imagem é uma estratégia discursiva que deve ser analisada. Não prova automaticamente que todas as afirmações históricas da conferência estejam corretas.</p>'),
 fill('Completa a distinção.', 'O respeito dirige-se às [1]; a crítica examina as [2].',[(['pessoas','teorias','símbolos'],0),(['ideias','formas','origens'],0)],'Separar pessoas e ideias permite discutir razões sem reduzir o interlocutor a uma etiqueta. Isso não obriga a aceitar como verdadeira qualquer afirmação.'),
 order('Ordena a construção de uma discordância fundamentada.', ['Identificar a ideia em discussão','Apresentar uma razão ou uma prova contrária','Explicar a relação entre prova e conclusão','Responder à ideia sem atacar a pessoa'],'A discordância torna-se verificável quando explicita o seu fundamento. A identidade do interlocutor não decide por si só o valor da tese.'),
 underline('Seleciona a palavra que marca o contraste entre impor e expor.', 'não pretendemos impor as nossas opiniões, mas simplesmente expô-las', [6], '«Mas» contrapõe duas maneiras de se relacionar com o auditório. A exposição admite uma resposta; a imposição procura dispensar esse exame.'),
 choice('Que efeito produz admitir a discordância do público?', ['Constrói uma imagem de abertura à discussão.', 'Demonstra a verdade de todas as teses futuras.', 'Dispensa a apresentação de razões verificáveis.'],0,'A admissão participa no ethos do orador. Uma imagem de abertura não substitui as provas nem garante a validade de todos os argumentos.'),
 vf('Respeitar uma pessoa obriga a considerar igualmente válidas todas as suas afirmações.',False,'O respeito não elimina os critérios de verdade, relevância ou coerência. É possível criticar uma afirmação com rigor e preservar a dignidade da pessoa.'),
 read('Duas respostas, duas relações','<p>Respostas criadas para esta lição. A: Essa conclusão ignora o documento que acabaste de citar. B: Pessoas como tu não merecem ser ouvidas.</p><p>A primeira aponta uma dificuldade que pode ser examinada. A segunda exclui a pessoa sem responder à razão apresentada. O desacordo não se torna mais forte por se transformar em ataque pessoal.</p>'),
 pairs('Classifica os procedimentos.',[['Confrontar uma tese com um documento','Refutação apoiada numa prova'],['Excluir alguém pela sua identidade','Ataque à pessoa'],['Admitir que uma objeção é pertinente','Limite reconhecido']], 'A classificação orienta a revisão de uma resposta. Não é a intensidade da discordância que distingue os casos, mas o objeto e o fundamento da crítica.'),
 choice('Que revisão torna a resposta B discutível com razões?', ['Nomear a conclusão contestada e explicar a objeção.', 'Repetir a exclusão com palavras ainda mais duras.', 'Trocar a identidade visada por uma outra identidade.'],0,'A revisão desloca a resposta para a ideia e permite contestação fundamentada. Intensificar ou trocar o alvo pessoal conserva o mesmo problema.'),
 fill('Completa uma regra.', 'O ethos é [1] de quem fala construída no discurso; a tese precisa de [2].',[(['uma imagem','uma certeza','a biografia'],0),(['provas','elogios','aliança'],0)],'O ethos influencia a relação com o público. A imagem construída no discurso não equivale à biografia de quem fala. A avaliação da tese continua a exigir fundamentos, e não apenas confiança na pessoa que a apresenta.'),
 order('Prepara uma intervenção breve.', ['Resumir a posição alheia sem a deformar','Assinalar o ponto exato de divergência','Apresentar uma razão pertinente','Indicar o que te faria rever a conclusão'],'A possibilidade de revisão torna explícito que a discussão procura conhecimento. Não significa abandonar antecipadamente a posição defendida.'),
 choice('Que pergunta permite avaliar uma discussão?', ['As razões apresentadas respondem à ideia debatida?', 'O número de aplausos torna dispensáveis as provas?', 'A origem de quem fala decide sempre quem tem razão?'],0,'A pertinência das razões liga a resposta ao problema. A popularidade e a origem da pessoa não substituem esse exame.'),
 vf('Podemos analisar a abertura da conferência sem assumir como factos todas as suas interpretações históricas.',True,'A análise discursiva estuda a relação com o público e os procedimentos argumentativos. A confirmação histórica das teses exige investigação própria.'),
 read('Para levar','<p class="levar">Discordar de uma ideia não exige excluir a pessoa que a apresenta.</p><p>Explica como Antero prepara a discussão e distingue a imagem do orador da prova de uma tese.</p>','Para levar'),
])

lesson('m6-f15','Quem faz a rua',2,'m6-f12',
 'Que revela o olhar sobre quem trabalha na cidade?',[
 read('Quem faz a rua','<p class="abre">Passas numa rua pronta. Quem a fez? Um poema pode tornar visível o trabalho e, ao mesmo tempo, revelar os limites de quem o observa.</p><p>Vais distinguir pormenor sensorial, imagem poética e avaliação em «Cristalizações».</p>','Abre'),
 read('O essencial','<p>A poesia de Cesário Verde cruza observação da cidade, sensações e transformação imaginativa. O sujeito poético seleciona e interpreta: não funciona como uma câmara neutra.</p><p>Uma comparação pode tornar um corpo visível e também enquadrá-lo por um olhar social. A análise pergunta o que se observa e o que se projeta sobre o observado.</p>','O essencial'),
 read('O trabalho ganha forma','<blockquote>«Faz frio. Mas, depois d’uns dias de aguaceiros,<br>Vibra uma immensa claridade crua.<br>De cocaras, em linha os calceteiros,<br>Com lentidão, terrosos e grosseiros,<br>Calcam de lado a lado a longa rua.»</blockquote><p>Cesário Verde, «Cristalizações» (na edição, «Crystalisações»), em <i>O Livro de Cesario Verde</i>, edição de Silva Pinto, Lisboa, 1887. Primeira estrofe, transcrição do <a href="'+CESARIO+'" target="_blank" rel="noopener">Projeto Gutenberg, com o poema integral</a>. Conserva-se a grafia histórica; «de cocaras» corresponde a «de cócoras».</p><p>A luz, a postura e os movimentos apresentam uma rua em construção. As palavras avaliativas também fazem parte desse enquadramento.</p>'),
 choice('Que leitura articula sensação e trabalho?', ['A luz e as posturas tornam o esforço visível.', 'A luz elimina qualquer presença humana na rua.', 'A luz demonstra a opinião de todos os operários.'],0,'A claridade acompanha corpos e ações. O poema não nos dá, por isso, acesso automático ao pensamento de cada trabalhador.'),
 vf('A presença de pormenores observáveis torna o sujeito poético inteiramente neutro.',False,'Selecionar pormenores e usar palavras avaliativas já constrói um olhar. A observação pode coexistir com interpretações e imagens.'),
 pairs('Distingue os elementos da primeira estrofe.',[['Faz frio','Sensação térmica'],['De cocaras','Postura corporal'],['terrosos e grosseiros','Caracterização pelo olhar da voz']], 'Os elementos pertencem a planos diferentes e atuam em conjunto. A postura torna o trabalho concreto; a caracterização revela a maneira de o apresentar.'),
 read('O corpo e a imagem','<blockquote>«Bom tempo. E os rapagões, morosos, duros, baços,<br>Cuja columna nunca se endireita,<br>Partem penedos; cruzam-se estilhaços.<br>Pesam enormemente os grossos maços,<br>Com que outros batem a calçada feita.»</blockquote><p>Cesário Verde, mesmo poema e edição. «Columna» corresponde a coluna; os maços são ferramentas usadas para bater. A postura curvada e o peso das ferramentas tornam sensível o esforço.</p><p>Mais adiante, o sujeito aproxima a roupa do povo de uma bandeira e lê nela sinais. Essa passagem transforma a observação em projeção simbólica, não numa opinião pronunciada pelos trabalhadores.</p>'),
 fill('Completa a distinção.', 'A ferramenta participa na [1] do trabalho; a bandeira é uma leitura [2].',[(['descrição','recordação','antevisão'],0),(['simbólica','documental','biográfica'],0)],'O trabalho fornece elementos concretos. A leitura simbólica nasce do modo como o sujeito os relaciona, e deve ser atribuída a esse olhar.'),
 order('Ordena uma análise da representação do trabalho.', ['Localizar uma postura ou uma ferramenta','Explicar a sensação de esforço que produz','Identificar uma avaliação ou uma imagem','Distinguir o observado do que a voz projeta'],'O percurso conserva o corpo concreto e interroga o enquadramento. Uma leitura apenas simbólica poderia apagar quem trabalha.'),
 underline('Seleciona a palavra que intensifica o peso das ferramentas.', 'Pesam enormemente os grossos maços,', [1], '«Enormemente» intensifica o peso e contribui para a perceção do esforço. A escolha verbal transforma a informação numa experiência sensível.'),
 choice('Que conclusão respeita a posição de quem observa?', ['A voz interpreta os corpos através das suas imagens.', 'Os corpos confirmam uma opinião dita por todos eles.', 'A voz regista todos os pormenores sem fazer escolhas.'],0,'A imagem pertence à construção poética. Não deve ser atribuída aos trabalhadores como se eles a tivessem pronunciado ou confirmado.'),
 vf('Descrever a dureza do trabalho obriga a idealizar todos os comportamentos dos trabalhadores.',False,'O reconhecimento do esforço não transforma as pessoas em figuras sem contradições. O poema pode apresentar relações e olhares desconfortáveis.'),
 read('Uma atriz também vai trabalhar','<p>Na parte final, surge uma atriz a caminho do ensaio. O poema mostra a atenção dos trabalhadores sobre ela e as dificuldades da passagem. Não basta classificá-la como uma figura sem trabalho: o destino indicado é o ensaio.</p><p>A cidade reúne corpos com tarefas e vulnerabilidades diferentes. A análise pode reconhecer o trabalho dos calceteiros sem apagar o desconforto produzido pelo olhar dirigido à mulher.</p>'),
 pairs('Relaciona os planos da cena urbana.',[['Calceteiros a preparar a rua','Trabalho material da cidade'],['Atriz a caminho do ensaio','Outro percurso de trabalho'],['Olhar dirigido à mulher','Relação que merece interpretação']], 'Os planos coexistem. Reconhecer um não exige negar os outros, e a cena torna-se mais complexa quando se conservam essas relações.'),
 choice('Que mudança criativa testa os limites do olhar?', ['Imaginar a rua vista pela atriz, como texto criado.', 'Atribuir à atriz pensamentos inventados como citação.', 'Apagar os operários e chamar ao resultado uma prova.'],0,'Uma perspetiva criada pode explorar o que o poema não revela, desde que seja identificada como criação. Não se confunde com informação da obra.'),
 fill('Completa uma regra de leitura.', 'A criação pode abrir uma [1]; a análise precisa de uma [2].',[(['hipótese','conclusão','sentença'],0),(['prova','ficção','lenda'],0)],'Imaginar e demonstrar são operações diferentes. A criação explora possibilidades; a análise sustenta o que afirma com elementos do texto.'),
 order('Planeia uma comparação com outro poema urbano.', ['Escolher uma figura de trabalho em cada poema','Observar os pormenores sensoriais','Comparar as avaliações de cada voz','Concluir sobre a visibilidade dada às pessoas'],'Comparar a cidade não é apenas contar ruas ou edifícios. O modo de tornar pessoas visíveis pode revelar diferenças decisivas entre os poemas.'),
 choice('Que conclusão liga forma poética e relação social?', ['As imagens mostram esforço e revelam um olhar situado.', 'As imagens substituem as pessoas por factos sem interpretação.', 'As imagens garantem que todos se sentem da mesma maneira.'],0,'A forma torna o esforço sensível e permite interrogar quem observa. Não fornece um retrato neutro nem uma experiência igual para todas as pessoas.'),
 vf('Reconhecer o olhar situado da voz impede-nos de estudar os pormenores concretos do trabalho.',False,'Os pormenores continuam a ser essenciais. A leitura ganha rigor ao relacionar aquilo que é observado com a forma como é selecionado e interpretado.'),
 read('Para levar','<p class="levar">Ver quem faz a cidade também exige perguntar quem está a olhar.</p><p>Relaciona uma ferramenta, uma sensação e uma avaliação. Explica por que razão a atriz não deve ser reduzida a uma figura que apenas passa.</p>','Para levar'),
])

lesson('m2-f15','Uma língua, várias formas',2,'m2-f11',
 'Que diferenças pertencem ao lugar, ao tempo ou a outra língua?',[
 read('Uma língua, várias formas','<p class="abre">Uma palavra diferente não é automaticamente um erro. Mas também não basta encontrar uma diferença para saber de onde ela vem.</p><p>Vais distinguir lugar, tempo, situação e presença de outra língua, regressando à linguagem da <i>Farsa de Inês Pereira</i>.</p>','Abre'),
 read('O essencial','<p>A <strong>variação geográfica</strong> relaciona diferenças com comunidades e lugares; a <strong>mudança histórica</strong>, com o tempo. O <strong>registo</strong> depende da situação de comunicação. Uma pessoa pode adaptar o registo sem mudar de variedade nacional.</p><p>Uma língua crioula é uma língua com organização própria, não uma forma errada de português. A diferença entre línguas não se reduz à diferença entre variedades de uma língua.</p>','O essencial'),
 read('Diferenças documentadas','<p>Margarita Correia apresenta «ônibus/autocarro» e «bolsista/bolseiro» como exemplos de variantes lexicais no artigo <a href="'+VARIEDADES+'" target="_blank" rel="noopener">«Variantes ou variedades de português?», <i>Ciberdúvidas da Língua Portuguesa</i>, 17 de janeiro de 2023</a>. São formas associadas às variedades brasileira e europeia.</p><p>O recurso <a href="https://estudoemcasaapoia.dge.mec.pt/index.php/recurso/lingua-portuguesa-no-mundo-0" target="_blank" rel="noopener">«A língua portuguesa no mundo», DGE/#EstudoEmCasa</a>, propõe estudar variedades e crioulos. Aqui, os exemplos lexicais provêm do artigo identificado, não de uma transcrição do vídeo.</p><p>Não precisas de conhecer todas as variedades para fazer uma classificação: precisas de saber que informação sustenta a diferença observada.</p>'),
 choice('Que diferença exemplifica o par «autocarro» e «ônibus»?', ['Uma variação lexical entre variedades nacionais.', 'Uma oposição entre duas línguas sem relação.', 'Uma mudança de pessoa numa conjugação verbal.'],0,'As duas palavras são apresentadas como variantes lexicais do português. Não correspondem a duas formas flexionadas do mesmo verbo nem a línguas sem relação.'),
 vf('Uma variedade nacional corresponde a uma única maneira de falar usada por toda a população.',False,'Uma variedade nacional contém diversidade interna. O lugar, os grupos e as situações não deixam de produzir diferenças dentro de um país.'),
 pairs('Liga o tipo de comparação ao fenómeno em análise.',[['Usos de comunidades em lugares diferentes','Variação geográfica'],['Usos documentados em épocas diferentes','Mudança histórica'],['Pedidos à mesma pessoa em situações diferentes','Mudança de registo']], 'A classificação depende do eixo comparado. Um caso pode envolver vários eixos; é necessário indicar qual deles se está a observar.'),
 read('Regressar à Farsa','<blockquote>«Señora, tengo-os servido<br>Y vos a mi despreciado;»</blockquote><p>Gil Vicente, <i>Farsa de Inês Pereira</i> (1523), fala do Ermitão, conforme a <a href="'+FARSA+'" target="_blank" rel="noopener">transcrição integral na Wikisource</a>. Conserva-se a forma do testemunho transcrito.</p><p>A presença de castelhano na peça não é um exemplo de português brasileiro. A distância histórica de uma grafia portuguesa e a presença de outra língua são problemas diferentes. Uma grafia, por si só, também não permite reconstruir toda a pronúncia.</p>'),
 fill('Completa a distinção.', 'Comparar lugares permite estudar a variação [1]; comparar épocas permite estudar a mudança [2].',[(['geográfica','cronológica','situacional'],0),(['histórica','geográfica','estilizada'],0)],'Os nomes identificam eixos de análise. Saber de onde e de quando vêm os testemunhos é parte da prova, não um detalhe acessório.'),
 order('Ordena uma investigação de uma diferença linguística.', ['Registar as formas observadas','Identificar a origem e a data dos exemplos','Comparar o mesmo fenómeno em contexto','Classificar a diferença com uma justificação'],'A classificação vem depois da identificação das fontes. A aparência de uma palavra não basta para atribuir nacionalidade a quem a usa.'),
 underline('Seleciona a palavra que torna abusiva esta generalização criada.', 'Uma palavra revela sempre a nacionalidade de quem fala.', [3], '«Sempre» transforma uma pista possível numa certeza universal. As pessoas podem usar formas de várias origens e adaptar o vocabulário à situação.'),
 choice('Que informação ajuda a distinguir tempo e lugar?', ['A data e a comunidade dos exemplos comparados.', 'O tamanho e a cor das letras usadas nos exemplos.', 'A ordem e o número das páginas dos dois exemplos.'],0,'A data e a comunidade permitem testar os eixos histórico e geográfico. Os aspetos de apresentação não demonstram a origem da diferença linguística.'),
 vf('Uma língua crioula deve ser corrigida até se tornar português padrão.',False,'Uma língua crioula tem estrutura própria. Descrevê-la como português defeituoso confunde sistemas linguísticos e desvaloriza injustificadamente os seus falantes.'),
 read('Adequação sem desvalorização','<p>Pedidos criados para esta lição. A: Podes mandar-me a informação? B: Solicito o envio da informação.</p><p>A diferença pode relacionar-se com a situação e a relação entre as pessoas. Não permite concluir que uma delas é mais inteligente. Numa produção escolar, aplicas a norma pedida, distinguindo adequação de inferioridade linguística.</p>'),
 pairs('Relaciona a conclusão com o cuidado necessário.',[['Uma palavra tem uso noutra variedade','Confirmar o uso numa fonte'],['Um pedido muda de formulação','Observar a situação comunicativa'],['Uma fala está noutra língua','Não a classificar como erro de português']], 'Cada conclusão pede um tipo de informação. Os exemplos não servem para ordenar pessoas por valor, mas para descrever usos com precisão.'),
 choice('Que alteração adapta o registo sem mudar o assunto?', ['Reformular o mesmo pedido para uma entidade pública.', 'Substituir o pedido por uma descrição de uma paisagem.', 'Trocar a informação pedida por uma narrativa de infância.'],0,'A reformulação conserva a finalidade e adapta a relação comunicativa. As outras opções mudam o conteúdo e não isolam a diferença de registo.'),
 fill('Completa uma regra de análise.', 'A diferença precisa de [1]; a adequação depende da [2].',[(['contexto','correção','silêncio'],0),(['situação','pronúncia','população'],0)],'Contexto e situação permitem compreender a função das formas. Uma palavra diferente, isolada, não demonstra erro nem permite uma conclusão sobre a pessoa.'),
 order('Planeia um pequeno levantamento de variantes.', ['Escolher um conceito comum','Recolher formas em fontes identificadas','Anotar comunidade e contexto de uso','Apresentar semelhanças sem hierarquizar falantes'],'A recolha exige documentação e contexto. Não basta colecionar palavras curiosas ou imitar pronúncias para demonstrar uma variedade.'),
 choice('Que conclusão respeita os exemplos estudados?', ['O português admite formas diferentes documentadas.', 'O português exige uma forma única em todos os países.', 'O português antigo equivale à variedade brasileira atual.'],0,'Os exemplos mostram diversidade dentro da língua. A mudança histórica e a variação geográfica continuam a ser dimensões distintas.'),
 vf('Reconhecer a diversidade impede aprender a norma pedida numa produção escolar.',False,'É possível aprender convenções de uma situação e reconhecer outros usos legítimos. Adequação não exige transformar toda a diferença em inferioridade.'),
 read('Para levar','<p class="levar">Antes de chamar erro a uma diferença, identifica o que estás a comparar.</p><p>Explica um caso de variação geográfica, distingue-o de mudança histórica e indica que informação te permite fazê-lo.</p>','Para levar'),
])

lesson('m3-f19','Mudar já não é o mesmo',1,'m3-f09',
 'Que diferença há entre voltar a primavera e voltar a ser quem eras?',[
 read('Mudar já não é o mesmo','<p class="abre">A primavera regressa. Uma experiência regressa da mesma maneira? Um soneto pode começar com uma regra geral e terminar por a tornar mais difícil.</p><p>Vais acompanhar a mudança de escala, do mundo à memória, até à surpresa final.</p>','Abre'),
 read('O essencial','<p>O <strong>soneto</strong> organiza catorze versos em dois quartetos e dois tercetos. A interpretação acompanha a relação entre essas partes, não apenas a contagem.</p><p>Em «Mudam-se os tempos, mudam-se as vontades», a mudança atravessa o mundo, a experiência e a própria forma de mudar. «Soía» significa costumava; «mor», maior.</p>','O essencial'),
 read('O mundo e a memória','<blockquote>«Mudam-se os tempos, mudam-se as vontades,<br>Muda-se o ser, muda-se a confiança;<br>Todo o mundo é composto de mudança,<br>Tomando sempre novas qualidades.»</blockquote><blockquote>«Continuamente vemos novidades,<br>Diferentes em tudo da esperança;<br>Do mal ficam as mágoas na lembrança,<br>E do bem, se algum houve, as saudades.»</blockquote><p>Luís de Camões, «Mudam-se os tempos, mudam-se as vontades», primeiros dois quartetos, transcrição da <a href="'+CAMOES+'" target="_blank" rel="noopener">RTP Ensina, com o poema integral</a>. O poema está em domínio público; a página não indica uma edição impressa.</p>'),
 choice('Que relação se estabelece entre novidade e esperança?', ['A experiência diverge daquilo que se esperava.', 'A experiência realiza tudo aquilo que se esperava.', 'A experiência elimina qualquer forma de memória.'],0,'O segundo quarteto apresenta novidades diferentes da esperança. A mudança não surge apenas como variedade neutra: envolve desajuste e memória afetiva.'),
 vf('O primeiro quarteto limita a mudança ao tempo meteorológico.',False,'A enumeração inclui vontades, ser e confiança. A regra é ampla e prepara a passagem para a experiência humana, não apenas para as estações.'),
 pairs('Liga cada elemento ao plano que desenvolve.',[['Vontades e confiança','Mudança da experiência humana'],['Mágoas e saudades','Persistência afetiva na memória'],['Todo o mundo','Alargamento da afirmação inicial']], 'O poema articula uma proposição ampla com efeitos particulares. O que muda pode deixar marcas, pelo que mudança não significa apagamento total.'),
 read('A natureza e a surpresa','<blockquote>«O tempo cobre o chão de verde manto,<br>Que já coberto foi de neve fria,<br>E enfim converte em choro o doce canto.»</blockquote><blockquote>«E, afora este mudar-se cada dia,<br>Outra mudança faz de mor espanto:<br>Que não se muda já como soía.»</blockquote><p>Luís de Camões, mesmo soneto, dois tercetos, transcrição da RTP Ensina. O verde sobre o chão antes coberto de neve permite pensar o regresso das estações; o canto transformado em choro introduz uma mudança afetiva.</p><p>O final não diz simplesmente que tudo deixou de mudar. Apresenta como espantosa uma alteração na própria maneira de mudar.</p>'),
 fill('Completa a diferença.', 'A natureza sugere um [1]; a experiência conserva uma [2].',[(['ciclo','corte','limite'],0),(['memória','promessa','certeza'],0)],'O regresso natural não garante a recuperação da experiência anterior. As mágoas e as saudades tornam a memória parte do problema da mudança.'),
 order('Ordena o percurso da reflexão no soneto.', ['Afirmar a mudança do mundo e das vontades','Observar o desajuste entre novidade e esperança','Confrontar natureza e transformação afetiva','Estranhar a mudança na própria forma de mudar'],'O último terceto não repete simplesmente a abertura. Reorienta-a e obriga o leitor a reconsiderar aquilo que parecia uma regra evidente.'),
 underline('Seleciona a palavra que introduz a diferença entre antes e agora.', 'Que não se muda já como soía.', [4], '«Já», associado à negação e à comparação com «soía», marca a diferença atual. A expressão não elimina toda a mudança: altera a sua relação com o passado.'),
 choice('Que leitura do último verso conserva a sua dificuldade?', ['A maneira de mudar já não é a de antes.', 'O mundo deixou de mudar em qualquer aspeto.', 'O tempo volta sempre ao mesmo ponto exato.'],0,'O verso compara modos de mudar. Reduzi-lo à imobilidade ou ao regresso idêntico apagaria o espanto introduzido pelo terceto.'),
 vf('As saudades mostram que tudo o que passou desapareceu sem deixar qualquer marca.',False,'A saudade é precisamente uma relação com o que se perdeu ou ficou distante. A mudança pode conviver com a persistência na memória.'),
 read('Uma experiência de leitura','<p>Frases criadas para esta lição. A: Voltou a primavera ao jardim. B: Voltei ao jardim, mas já não o reconheci da mesma maneira.</p><p>O lugar pode ser o mesmo e a relação com ele ter mudado. A comparação não é uma paráfrase do soneto: serve para experimentar a diferença entre repetição exterior e transformação da experiência.</p>'),
 pairs('Classifica os três movimentos.',[['Neve seguida de verde','Alternância natural'],['Canto convertido em choro','Transformação afetiva'],['Mudar de modo diferente do passado','Reflexão sobre a própria mudança']], 'A interpretação ganha precisão quando conserva os planos e explica a sua relação. Nem todas as mudanças apresentadas têm o mesmo sentido.'),
 choice('Que alteração retiraria a surpresa final?', ['Terminar apenas com a regra de que tudo muda.', 'Conservar a comparação com a mudança de antes.', 'Manter a palavra «espanto» antes do último verso.'],0,'A repetição simples da regra inicial apagaria a reflexão sobre a maneira de mudar. O final faz mais do que confirmar a primeira afirmação.'),
 fill('Completa uma conclusão.', 'O soneto parte de uma [1] geral e chega a uma [2] dessa regra.',[(['regra','prova','norma'],0),(['revisão','certeza','recusa'],0)],'A organização conduz da afirmação ao espanto. A revisão não exige negar toda a abertura, mas torna mais complexa a relação entre presente e passado.'),
 order('Prepara a interpretação do último terceto.', ['Explicar o sentido de soía','Identificar o contraste entre antes e agora','Relacionar o verso com o espanto anunciado','Confrontar a conclusão com a abertura'],'A interpretação lexical apoia a relação entre partes. Explicar apenas uma palavra não seria suficiente para compreender o movimento do soneto.'),
 choice('Que comparação com outro poema seria mais produtiva?', ['Comparar o papel da memória em duas mudanças.', 'Contar só as palavras iguais em dois poemas.', 'Provar que toda a mudança tem sempre o mesmo efeito.'],0,'A memória permite comparar relações entre experiência e tempo. A comparação deve conservar diferenças, em vez de procurar uma fórmula universal.'),
 vf('Uma repetição verbal pode organizar uma reflexão que termina por rever a própria ideia repetida.',True,'A insistência inicial prepara o reconhecimento da regra. O final pode depois deslocá-la, criando uma descoberta que depende desse percurso anterior.'),
 read('Para levar','<p class="levar">A surpresa não é apenas mudar: é já não mudar da mesma maneira.</p><p>Relaciona uma imagem da natureza, uma marca da memória e o último verso. Explica o que o final acrescenta à abertura.</p>','Para levar'),
])

lesson('m5-f17','A carta que não chegou',1,'m5-f04',
 'Que muda quando descobres quem impediu uma mensagem de chegar?',[
 read('A carta que não chegou','<p class="abre">Uma carta fica sem resposta. Isso prova indiferença? Talvez falte saber se chegou ao destinatário.</p><p>Vais observar como uma informação revelada mais tarde altera a leitura de um silêncio em <i>Amor de Perdição</i>.</p>','Abre'),
 read('O essencial','<p>Na comunicação, é necessário distinguir <strong>emissor</strong>, <strong>destinatário</strong>, <strong>mensagem</strong> e <strong>canal</strong>. Uma interferência pode impedir o contacto sem que o destinatário o saiba.</p><p>A narração pode revelar depois uma informação desconhecida pelas personagens. O leitor revê então uma interpretação anterior: a ordem de contar também produz conhecimento.</p>','O essencial'),
 read('A descoberta posterior','<blockquote class="prosa">«Escrevia a mãe a Simão, e não recebia resposta. Pensava ela que o filho não respondia: anos depois, vimos entre os papéis de meu pai todas as cartas que ela escrevera. Já se vê que o pai as fazia tirar no correio.»</blockquote><p>Camilo Castelo Branco, <i>Amor de Perdição</i>, capítulo XII, edição de Ivo Castro, Lisboa, Imprensa Nacional, 2020, p. 120. A passagem pertence à memória familiar atribuída à irmã de Simão. O texto de Camilo está em domínio público.</p><p><a href="'+CARTA+'" target="_blank" rel="noopener">Consulta a edição integral da Imprensa Nacional</a>. Procura o capítulo XII e a página impressa 120. O recorte não é uma carta de Teresa: trata das cartas da mãe para Simão.</p>'),
 choice('Que informação altera a explicação do silêncio?', ['O pai mandava retirar as cartas no correio.', 'A mãe decidiu não voltar a escrever.', 'Simão respondeu a todas as mensagens.'],0,'A descoberta das cartas revela uma interferência no canal. A falta de resposta deixa de poder ser atribuída automaticamente a uma decisão de Simão.'),
 vf('Não receber resposta prova que o destinatário leu e recusou a mensagem.',False,'A ausência de resposta é um resultado com várias explicações possíveis. Neste recorte, a interceção impede concluir que Simão recebeu as cartas.'),
 pairs('Relaciona cada elemento com a sua função.',[['A mãe que escreve','Emissora das mensagens'],['Simão','Destinatário pretendido'],['Interceção no correio','Interferência no canal']], 'O destinatário pretendido não é necessariamente quem recebe materialmente a mensagem. A interceção altera o percurso sem mudar a intenção da emissora.'),
 read('Quem sabe o quê','<p>A mãe interpreta a ausência de resposta sem conhecer a interceção. A recordação posterior fornece ao leitor uma informação que ela não tinha naquele momento.</p><p>Essa diferença permite rever uma conclusão. Não significa que o recorte revele todos os pensamentos de Simão ou todas as razões do pai. A explicação comprovada deve manter o seu alcance.</p>'),
 fill('Completa a distinção.', 'A falta de resposta é uma [1]; a indiferença seria uma [2].',[(['observação','justificação','confirmação'],0),(['inferência','ocorrência','confirmação'],0)],'Uma observação pode admitir explicações diferentes. A inferência sobre sentimentos exige provas que a ausência de resposta, sozinha, não fornece.'),
 order('Reconstrói a sequência dos acontecimentos referidos.', ['A mãe escreve a Simão','As cartas são retiradas no correio','A mãe não recebe resposta','Anos depois, as cartas são encontradas'],'A narração menciona primeiro o resultado e só depois explica a interceção. Reconstruir os acontecimentos distingue ordem temporal e ordem de revelação.'),
 underline('Seleciona as palavras que assinalam a distância temporal da descoberta.', 'anos depois, vimos entre os papéis de meu pai todas as cartas', [0,1], '«Anos depois» situa o momento em que surge a prova. O intervalo é decisivo para perceber que a mãe não dispunha dessa informação quando interpretava o silêncio.'),
 choice('Que efeito produz revelar a interceção mais tarde?', ['Obriga a rever a interpretação do silêncio.', 'Confirma sem alteração a culpa do destinatário.', 'Elimina a necessidade de distinguir as vozes.'],0,'A nova informação muda a explicação do que já tinha sido contado. Esse efeito depende da distribuição do conhecimento ao longo da narrativa.'),
 vf('O recorte permite afirmar com certeza todos os sentimentos de Simão perante estas cartas.',False,'O texto explica o bloqueio das mensagens. Não apresenta uma reação de Simão à leitura dessas cartas nem permite inventar o que ele teria sentido.'),
 read('Mudar a ordem de contar','<p>Resumo didático A: a mãe escreve, não recebe resposta e só depois se descobre a interceção. Resumo didático B: anuncia-se primeiro a interceção e conta-se depois a falta de resposta.</p><p>Os acontecimentos podem ser os mesmos. Em B, o leitor sabe antecipadamente aquilo que a mãe ignora; em A, a explicação posterior obriga a uma revisão.</p>'),
 pairs('Distingue três planos.',[['O que aconteceu às cartas','Percurso material da mensagem'],['O que a mãe pensava','Interpretação da personagem'],['Quando o leitor descobre o bloqueio','Organização da informação narrativa']], 'Separar os planos permite explicar o efeito da ordem. Uma alteração na narração não exige uma alteração dos acontecimentos narrados.'),
 choice('Que reescrita conserva os factos e muda a informação?', ['Antecipar a interceção na ordem dos acontecimentos.', 'Inventar uma resposta de Simão a todas as cartas.', 'Eliminar o pai e atribuir toda a interceção a Teresa.'],0,'A primeira proposta reorganiza os mesmos factos. As outras mudam os acontecimentos e não servem para isolar o efeito da ordem narrativa.'),
 fill('Completa uma regra de leitura.', 'A nova prova permite [1] a explicação, sem autorizar [2] sentimentos.',[(['rever','fixar','negar'],0),(['inventar','observar','comparar'],0)],'A revisão corrige o que era apenas uma hipótese. Não preenche todas as lacunas da história nem transforma possibilidades em estados interiores comprovados.'),
 order('Prepara uma resposta sobre a função da descoberta.', ['Identificar a interpretação inicial da mãe','Citar a informação sobre a interceção','Explicar a revisão exigida ao leitor','Indicar uma conclusão que continua sem prova'],'Uma resposta rigorosa liga o antes e o depois da informação. O limite da conclusão mostra que a análise não confunde explicação com adivinhação.'),
 choice('Que conclusão se apoia no recorte?', ['O controlo das cartas interfere na relação familiar.', 'O silêncio demonstra sempre a rejeição de uma relação.', 'A descoberta torna todas as personagens igualmente informadas.'],0,'A interceção limita o contacto e produz uma interpretação enganada. O texto não transforma o silêncio numa regra geral nem afirma conhecimento igual para todos.'),
 vf('Uma mensagem não entregue pode produzir consequências mesmo sem o destinatário a conhecer.',True,'A emissora interpreta a ausência de resposta e a relação é afetada. A comunicação também pode ser estudada através dos bloqueios e dos seus efeitos.'),
 read('Para levar','<p class="levar">Antes de interpretar um silêncio, confirma o percurso da mensagem.</p><p>Explica o que a mãe sabia, o que a descoberta acrescenta e como mudar a ordem de contar alteraria a posição do leitor.</p>','Para levar'),
])

lesson('m1-f21','Amar contra a vontade',1,'m1-f04',
 'Como se constrói uma vontade que não consegue realizar-se?',[
 read('Amar contra a vontade','<p class="abre">E se alguém quisesse deixar de amar, mas não conseguisse? Uma cantiga pode construir um conflito sem contar uma sucessão de acontecimentos.</p><p>Vais seguir o que a voz deseja, aquilo de que é capaz e o efeito do refrão.</p>','Abre'),
 read('O essencial','<p>Na cantiga de amor, a voz masculina pode apresentar o sofrimento amoroso, ou <strong>coita</strong>. Essa voz é uma construção poética, não uma declaração biográfica automática do trovador.</p><p>Uma hipótese introduzida por «se» permite imaginar uma possibilidade. A oposição entre desejar e conseguir sustenta esta cantiga de Pero da Ponte.</p>','O essencial'),
 read('Uma hipótese e um limite','<blockquote>«Se eu podesse desamar<br>a que me sempre desamou,<br>e podess’algun mal buscar<br>a quen me sempre mal buscou,<br>assi me vingaria eu<br>se eu podesse coita dar<br>a quen me sempre coita deu.»</blockquote><blockquote>«Mais sol non poss’eu enganar<br>meu coraçon, que m’enganou,»</blockquote><p>Pero da Ponte, «Se eu podesse desamar», cantiga 982, edição crítica <i>Universo Cantigas</i>, Universidade da Corunha, primeira estrofe e abertura da segunda. Conserva-se a grafia da edição. «Coita» significa sofrimento; «assi», assim; «non», não.</p><p><a href="'+CANTIGA+'" target="_blank" rel="noopener">Lê a cantiga completa e a paráfrase na edição crítica</a>. A hipótese de retribuir o sofrimento é contrariada pela incapacidade de dominar o próprio coração.</p>'),
 choice('Que conflito aparece entre os dois recortes?', ['Deseja retribuir, mas não consegue dominar o amor.', 'Decide esquecer e consegue terminar logo o amor.', 'Recebe carinho e procura prolongar então o amor.'],0,'A primeira estrofe imagina a retribuição da dor. A abertura da segunda introduz a incapacidade de enganar o coração: a vontade não controla o sentimento.'),
 vf('A primeira estrofe afirma que a vingança já aconteceu.',False,'A hipótese depende de «se» e de formas como «podesse». O poema imagina uma capacidade que a voz não apresenta como realizada.'),
 pairs('Relaciona as marcas do recorte com a sua função.',[['Se eu podesse','Introdução de uma hipótese'],['sempre','Insistência na continuidade'],['Mais sol non poss’eu','Contraste com a incapacidade']], 'Os elementos organizam o conflito. A repetição de «sempre» intensifica a assimetria; a negativa impede ler a hipótese como um facto consumado.'),
 read('Quem dá e quem recebe','<p>Na primeira estrofe, o desejo troca as posições: quem recebeu sofrimento imagina passá-lo a quem o causou. A construção repete palavras com alterações de pessoa e de tempo.</p><p>Representar este desejo não equivale a recomendar a vingança. A leitura analisa uma voz em conflito; não transforma o seu desejo numa regra para as relações.</p>'),
 fill('Completa a distinção.', 'A vingança surge como [1]; a falta de domínio surge como [2].',[(['hipótese','memória','promessa'],0),(['limite','triunfo','engano'],0)],'Uma hipótese abre uma possibilidade no discurso. O limite mostra o que impede a voz de a concretizar, mantendo a tensão do poema.'),
 order('Reconstrói o movimento dos recortes.', ['A voz imagina deixar de amar','Imagina retribuir o sofrimento','Nomeia a vingança como hipótese','Reconhece que não domina o coração'],'A ordem conduz de uma possibilidade desejada ao obstáculo interior. O segundo recorte modifica a leitura do primeiro sem apagar o desejo.'),
 underline('Seleciona a palavra que torna hipotético o desejo.', 'Se eu podesse desamar', [0], '«Se» introduz uma condição. Sem essa marca, e mudando a forma verbal, poderíamos passar de uma hipótese para uma afirmação de capacidade.'),
 choice('Que leitura explica a repetição de «coita» no refrão?', ['Insiste no desejo de retribuir o sofrimento.', 'Anuncia a resolução definitiva do sofrimento.', 'Retira à voz toda a lembrança do sofrimento.'],0,'O refrão retoma a relação entre dar e receber sofrimento. A insistência conserva o conflito, em vez de anunciar que já está resolvido.'),
 vf('A forma desamar prova que o sentimento já desapareceu.',False,'O verbo nomeia a ação desejada. É necessário ler a construção «se eu podesse»: ela não afirma que a voz tenha conseguido deixar de amar.'),
 read('Experimenta uma transformação','<p>Frases criadas para esta lição. A: Se pudesse esquecer, descansaria. B: Consegui esquecer e descansei.</p><p>As frases partilham o assunto, mas não o mesmo conflito. Em A, o descanso depende de uma capacidade; em B, o enunciado apresenta uma realização. Este contraste ajuda a perceber a importância da hipótese na cantiga.</p>'),
 pairs('Distingue três planos de leitura.',[['O que a voz deseja','Deixar de amar e retribuir a dor'],['O que a voz reconhece','Não dominar o próprio coração'],['O que a análise evita','Transformar o desejo em conselho']], 'Ler com rigor exige separar a vontade da personagem lírica, o seu limite e a posição de quem interpreta o texto.'),
 choice('Que transformação eliminaria o conflito estudado?', ['Afirmar que a voz conseguiu deixar de amar.', 'Repetir que a voz gostaria de deixar de amar.', 'Mostrar que a voz continua sem deixar de amar.'],0,'A realização retiraria a distância entre vontade e capacidade. As outras alterações manteriam ou intensificariam precisamente essa distância.'),
 fill('Completa uma conclusão.', 'A repetição reforça a [1]; a negativa revela a [2].',[(['insistência','indiferença','coincidência'],0),(['incapacidade','reciprocidade','superioridade'],0)],'Repetição e negação cooperam: a voz regressa ao desejo e encontra de novo o seu limite, em vez de avançar para uma solução.'),
 order('Prepara uma comparação com outra cantiga de amor.', ['Identificar o desejo de cada voz','Localizar o obstáculo em cada texto','Comparar o efeito das repetições','Concluir com uma diferença sustentada'],'O tema amoroso é apenas o ponto de partida. A comparação ganha precisão quando distingue desejos, obstáculos e formas de insistir.'),
 choice('Que comentário respeita o limite entre voz e autor?', ['A voz apresenta na cantiga um desejo de vingança.', 'Pero da Ponte realizou esta vingança na sua vida.', 'A cantiga recomenda esta vingança a todas as pessoas.'],0,'A primeira formulação atribui o desejo à voz que o texto constrói. As outras acrescentam uma biografia ou uma recomendação sem prova.'),
 vf('A incapacidade de deixar de amar pode ser o centro de uma cantiga sem uma sequência de aventuras.',True,'O movimento pode ser interior: hipótese, desejo e limite. A progressão da reflexão também organiza um texto, mesmo sem aventuras sucessivas.'),
 read('Para levar','<p class="levar">Desejar uma mudança e conseguir realizá-la são coisas diferentes.</p><p>Explica como a hipótese e a negativa constroem esse intervalo na cantiga. Indica uma repetição que mantenha o conflito vivo.</p>','Para levar'),
])

lesson('m2-f16','O riso muda de alvo',1,'m2-f02',
 'Como distinguir quem fala, quem é ridicularizado e o que se critica?',[
 read('O riso muda de alvo','<p class="abre">Duas pessoas podem rir da mesma cena e estar a rir de coisas diferentes. Como descobres o alvo da crítica?</p><p>Na entrada de Lianor Vaz, vais comparar o relato de uma personagem com a reação da Mãe.</p>','Abre'),
 read('O essencial','<p>O <strong>cómico de linguagem</strong> pode explorar duplos sentidos; o <strong>cómico de situação</strong> nasce das relações em cena. A <strong>sátira</strong> dirige a crítica a comportamentos e posições sociais.</p><p>É necessário distinguir a pessoa que fala, a pessoa visada e o comportamento exposto. Uma reação de uma personagem não equivale automaticamente à posição da obra.</p>','O essencial'),
 read('Um relato e uma resposta','<p>Lianor:</p><blockquote>«E hum clérigo, mana minha,<br>Pardeos, lançou mão de mi;<br>Não me podia valer»</blockquote><p>Mãe:</p><blockquote>«Hui! seria algum muchacho,<br>Que brincava por prazer?»</blockquote><p>Gil Vicente, <i>Farsa de Inês Pereira</i> (1523), entrada de Lianor Vaz, texto integral na Wikisource. Identificam-se as falantes; conserva-se a grafia da transcrição nos versos. «Clérigo» designa um membro do clero; «muchacho», um rapaz.</p><p><a href="'+FARSA+'" target="_blank" rel="noopener">Lê a cena completa no texto integral</a>. A resposta da Mãe reformula como brincadeira aquilo que Lianor apresenta como uma ação de que não conseguia defender-se.</p>'),
 choice('Que contraste se observa entre o relato e a resposta?', ['A resposta atenua a gravidade da ação relatada.', 'A resposta confirma todos os detalhes relatados.', 'A resposta impede qualquer interpretação da ação.'],0,'Lianor refere uma ação de que não conseguia defender-se. A Mãe apresenta a hipótese de uma brincadeira, deslocando a forma de a nomear.'),
 vf('A resposta da Mãe prova que a ação relatada foi uma brincadeira.',False,'A fala é a interpretação de uma personagem. Não se transforma em prova do acontecimento só por aparecer no diálogo.'),
 pairs('Distingue as funções dos três elementos.',[['Lianor Vaz','Pessoa que relata a ação'],['O clérigo referido','Figura visada no relato'],['A resposta da Mãe','Reação que atenua a gravidade']], 'Atribuir cada fala e cada ação evita fundir todas as posições numa só. O diálogo contém perspetivas que podem entrar em tensão.'),
 read('Uma palavra com dois sentidos','<p>Mãe:</p><blockquote>«Mana, conhecia-te ele?»</blockquote><p>Lianor:</p><blockquote>«Mas queria-me conhecer!»</blockquote><p>Na mesma cena, «conhecer» permite passar do reconhecimento de alguém para uma insinuação sexual. O efeito depende da pergunta, da resposta e do relato anterior.</p><p>Compara a pergunta da Mãe com a resposta de Lianor: a repetição do verbo mantém ou altera a perspetiva de quem escuta?</p>'),
 fill('Completa a leitura do diálogo.', 'O duplo sentido depende do [1]; a crítica exige identificar o [2].',[(['contexto','alfabeto','tamanho'],0),(['alvo da crítica','tema da conversa','tom do discurso'],0)],'A palavra isolada não produz toda a interpretação. O contexto permite reconhecer a insinuação e discutir a quem se dirige a crítica.'),
 order('Ordena uma análise responsável do cómico.', ['Atribuir a pergunta e a resposta','Identificar os sentidos da palavra','Relacionar o contraste com o relato','Explicar o comportamento que fica exposto'],'A análise parte da atribuição e chega ao efeito. Não usa uma classificação de cómico para dispensar a compreensão do que acontece.'),
 underline('Seleciona a palavra que opõe a resposta à pergunta.', 'Mas queria-me conhecer!', [0], '«Mas» introduz uma correção da perspetiva. A resposta conserva o verbo, mas desloca o sentido que a pergunta parecia atribuir-lhe.'),
 choice('Que comentário interpreta o duplo sentido sem o apagar?', ['Conhecer muda de sentido entre as falas.', 'Conhecer conserva só o sentido de reconhecer.', 'Conhecer deixa de ter relação com o contexto.'],0,'A repetição lexical esconde uma mudança de sentido. É essa deslocação, apoiada pelo contexto, que permite analisar o cómico de linguagem.'),
 vf('Identificar cómico de linguagem basta para explicar o alvo da crítica.',False,'A mudança de sentido de «conhecer» só se explica na relação com o relato de Lianor, com a reação da Mãe e com o clérigo referido. Nomear o mecanismo cómico, sozinho, não identifica o alvo da crítica.'),
 read('Muda a reação, muda a cena','<p>Reações criadas para esta lição, perante um relato. A: Isso não tem importância. B: Percebo que não conseguiste defender-te.</p><p>Não são falas de Gil Vicente. Servem para testar como a resposta de quem escuta pode minimizar uma ação ou reconhecer o que foi relatado. Alterar essa resposta transforma a relação em cena.</p>'),
 pairs('Liga cada procedimento ao seu efeito.',[['Atenuar a ação relatada','Diminuir a gravidade reconhecida'],['Repetir um verbo com outro sentido','Construir uma ambiguidade'],['Atribuir cada posição à sua falante','Evitar uma conclusão indevida']], 'As operações não são equivalentes. Uma descreve a reação, outra o mecanismo verbal e outra o cuidado necessário na interpretação.'),
 choice('Que decisão de encenação torna a reação da Mãe mais visível?', ['Criar uma pausa após a resposta que atenua.', 'Eliminar a resposta e conservar só o relato.', 'Acrescentar uma fala alheia sem a identificar.'],0,'Uma pausa pode dar atenção à resposta e ao seu efeito. A decisão deve ser apresentada como proposta de encenação, não como indicação original.'),
 fill('Completa uma conclusão prudente.', 'A fala de uma personagem exprime uma [1]; a interpretação precisa de outra [2].',[(['posição','certeza','sentença'],0),(['prova','verso','ritmo'],0)],'Uma posição em diálogo não vale por toda a obra. Para sustentar uma interpretação, relaciona-a com outras marcas da cena.'),
 order('Planeia uma comparação entre duas cenas satíricas.', ['Identificar quem fala em cada cena','Localizar o comportamento visado','Explicar o mecanismo cómico de cada uma','Comparar os efeitos sem confundir os alvos'],'Comparar apenas a presença de humor seria insuficiente. O alvo e o mecanismo podem mudar, mesmo quando ambas as cenas fazem parte de uma farsa.'),
 choice('Que pergunta aprofunda a relação entre relato e reação?', ['Como transforma a resposta a gravidade do relato?', 'Como prova o riso que a ação foi sempre inocente?', 'Como confirma toda a cena que o relato é uma mentira?'],0,'A primeira pergunta observa uma relação textual. As outras pressupõem conclusões que não foram demonstradas e apagam a distinção entre relato e reação.'),
 vf('Uma leitura atual pode discutir o efeito de uma resposta sem fingir que a cena foi escrita hoje.',True,'Contextualizar e interpretar não são operações incompatíveis. É possível reconhecer a distância histórica e analisar os efeitos das palavras na relação entre personagens.'),
 read('Para levar','<p class="levar">O mecanismo do riso e o alvo da crítica não são a mesma coisa.</p><p>Explica o duplo sentido, atribui as falas e indica o comportamento que a cena permite discutir. Não confundas a reação de uma personagem com uma prova.</p>','Para levar'),
])

lesson('m2-f14','As palavras também julgam',1,'m2-f16',
 'Como pode uma palavra caracterizar quem é nomeado e quem a usa?',[
 read('As palavras também julgam','<p class="abre">Chamar alguém por uma palavra pode fazer mais do que identificá-lo. Pode revelar uma expectativa, uma hierarquia ou um desprezo.</p><p>Vais observar a formação de uma palavra e o valor que recebe na fala de Inês.</p>','Abre'),
 read('O essencial','<p>A <strong>derivação</strong> forma palavras a partir de uma base e de afixos. Os sufixos diminutivos podem exprimir dimensão, afeto ou depreciação, conforme o contexto.</p><p>A <strong>flexão</strong> produz formas da mesma palavra, por exemplo no plural. Identificar um sufixo não basta: é necessário explicar o efeito da escolha lexical na cena.</p>','O essencial'),
 read('Antes de conhecer','<blockquote>«Deve ser um vilãozinho<br>Ei-lo, se vem penteando:<br>Será com algum ancinho?»</blockquote><p>Gil Vicente, <i>Farsa de Inês Pereira</i> (1523), fala de Inês antes da entrada de Pêro Marques, transcrição da Wikisource. «Ancinho» é um instrumento agrícola. A comparação associa antecipadamente a figura aos trabalhos rurais.</p><p><a href="'+FARSA+'" target="_blank" rel="noopener">Lê a fala e a entrada de Pêro Marques no texto integral</a>. Inês ainda está a imaginar o pretendente: a nomeação revela o seu próprio olhar.</p>'),
 choice('Que leitura explica «vilãozinho» neste contexto?', ['Marca uma avaliação depreciativa do pretendente.', 'Fornece uma medição objetiva da sua altura física.', 'Confirma uma manifestação inequívoca de ternura.'],0,'A associação ao ancinho e a antecipação da figura apoiam a depreciação. O sufixo sozinho não autorizaria concluir qual é o valor afetivo.'),
 vf('Todos os diminutivos exprimem obrigatoriamente carinho.',False,'O valor depende da situação e das palavras que rodeiam o diminutivo. Neste contexto, a imagem do ancinho contribui para uma avaliação depreciativa.'),
 pairs('Liga cada operação à descrição correta.',[['vilão → vilãozinho','Derivação por sufixação'],['vilão → vilões','Flexão em número'],['ancinho no retrato imaginado','Associação ao universo rural']], 'A primeira operação forma uma palavra derivada; a segunda produz o plural. A terceira já pertence à construção do retrato e ao seu efeito.'),
 read('O retrato revela dois lados','<p>Inês antecipa uma figura que considera pouco desejável. A fala caracteriza indiretamente o seu sistema de preferências: valoriza uma imagem de distinção e desvaloriza uma imagem rural.</p><p>Não é necessário adotar esse juízo para o analisar. A personagem nomeada e a personagem que nomeia são ambas objeto da leitura.</p>'),
 fill('Completa a análise.', 'O sufixo participa na [1] da palavra; o contexto esclarece a [2] de Inês.',[(['formação','pronúncia','contagem'],0),(['avaliação','profissão','formação'],0)],'A formação é uma observação linguística. A avaliação exige relacionar essa observação com a comparação e com as expectativas da personagem.'),
 order('Ordena a passagem da forma ao efeito.', ['Identificar a base e o sufixo','Ler a comparação que acompanha a palavra','Interpretar a avaliação do pretendente','Relacionar essa avaliação com o olhar de Inês'],'O processo evita tratar o sufixo como um rótulo de sentido fixo. A conclusão sobre a personagem resulta do encontro entre forma e contexto.'),
 underline('Seleciona a palavra que introduz uma expectativa ainda não confirmada.', 'Deve ser um vilãozinho', [0], '«Deve» apresenta uma suposição de Inês. Não se trata de uma descrição neutra feita depois de conhecer todos os comportamentos do pretendente.'),
 choice('Que distinção se deve conservar na interpretação?', ['O juízo de Inês difere de um retrato neutro.', 'O juízo de Inês equivale a uma prova neutra.', 'O juízo de Inês elimina qualquer outro olhar.'],0,'A fala pertence a uma personagem com preferências. O desenvolvimento da cena pode confirmar, complicar ou contrariar a antecipação que ela constrói.'),
 vf('Retirar o diminutivo apagaria necessariamente toda a depreciação do recorte.',False,'A comparação com o ancinho também participa na avaliação. Um efeito pode resultar de várias escolhas, e não apenas de uma palavra.'),
 read('A mesma forma, outros efeitos','<p>Exemplos criados para esta lição. A: Guardei a casinha de madeira da maqueta. B: A nossa casinha acolheu toda a família. C: É só uma casinha, não merece atenção.</p><p>A dimensão, o afeto e a depreciação podem sobrepor-se. Nas atividades seguintes, escolhe o valor tornado mais saliente pelo contexto apresentado.</p>'),
 pairs('Relaciona cada contexto criado com o valor mais saliente.',[['Casa numa maqueta','Dimensão reduzida'],['Casa que acolhe a família','Relação afetiva'],['Casa declarada sem valor','Avaliação depreciativa']], 'Os exemplos orientam uma leitura contextual, sem estabelecer um significado obrigatório para todos os usos futuros da mesma palavra.'),
 choice('Que alteração reduz mais diretamente o juízo sobre Pêro?', ['Trocar a antecipação por uma descrição observável.', 'Intensificar a comparação com instrumentos rurais.', 'Acrescentar outro diminutivo de valor depreciativo.'],0,'Uma descrição observável pode limitar a avaliação antecipada. As outras decisões reforçam precisamente o mecanismo de desvalorização estudado.'),
 fill('Completa a diferença.', 'A derivação cria uma palavra [1]; a flexão produz uma forma [2].',[(['derivada','alterada','corrigida'],0),(['gramatical','derivacional','avaliativa'],0)],'A distinção é morfológica: formação de palavras e variação gramatical não são a mesma operação, embora ambas possam ser observadas no discurso.'),
 order('Prepara uma explicação de quatro passos.', ['Citar a palavra em análise','Identificar o processo de formação','Apresentar uma pista do contexto','Explicar o que a escolha revela de Inês'],'Uma resposta completa liga estrutura, prova e efeito. Dizer apenas diminutivo deixaria por explicar a função da escolha na cena.'),
 choice('Que conclusão evita adotar o preconceito da personagem?', ['Inês associa o universo rural à falta de distinção.', 'O universo rural prova sempre a falta de inteligência.', 'A fala demonstra que o pretendente não tem valor.'],0,'A primeira frase atribui a avaliação a Inês. As outras convertem o olhar da personagem numa regra geral ou numa desvalorização assumida pela análise.'),
 vf('Uma palavra que nomeia alguém pode também caracterizar quem a escolhe.',True,'A escolha lexical revela valores, expectativas ou relações. Por isso, a análise pode estudar simultaneamente o retrato construído e o olhar de quem o constrói.'),
 read('Para levar','<p class="levar">Uma palavra pode nomear uma pessoa e revelar o olhar de outra.</p><p>Identifica a formação de «vilãozinho», apresenta uma pista contextual e explica a avaliação de Inês sem a transformar na tua.</p>','Para levar'),
])
